lemma transported_naturality' (hR : IsRealization R) (β : FibreAut Φ) {c c' : C}
    (u : R.obj c ⟶ R.obj c') (x : F.obj (R.obj c)) :
    (transported R e β c').hom (F.map u x) = F.map u ((transported R e β c).hom x)

lemma map_mem_removedSetIn {K L : Type*} [Field K] [DecidableEq K] [Algebra k K] [Field L]
    [DecidableEq L] [Algebra k L] (φ : K →ₐ[k] L) {P : (W.toAffine⁄K).Point}
    (hP : P ∈ removedSetIn W K ℓ M) : Point.map φ P ∈ removedSetIn W L ℓ M

lemma evalHom_congr {A : Type*} [CommRing A] [Algebra k A] {x y x' y' : A}
    (h : (W.toAffine⁄A).Equation x y) (hx : x = x') (hy : y = y') :
    evalHom W x y h = evalHom W x' y' (hx ▸ hy ▸ h)

theorem pullback_mem_ringAway_aux {𝒮 : Set (GeomPoint W)} (hD𝒮 : zeroSet W D ⊆ 𝒮)
    {g : AffAut W} (hm : g.m ≠ 0 → xOf g.m ∈ T) (hg : ∀ P ∈ 𝒮, g⁻¹.act _ P ∈ 𝒮) {f : funField W}
    (hf : f ∈ ringAway W 𝒮) : pullback W g f ∈ ringAway W 𝒮

lemma isAffStable_torsionSet {ℓ : ℕ} {M : AddSubgroup W.toAffine.Point}
    (hM : ∀ m ∈ M, ℓ • m = 0) (pm : Bool) :
    IsAffStable (torsionSet W ℓ) (affGroup W M pm)

theorem isUnit_of_forall_algHom_ne_zero {k R : Type*} [Field k] [CommRing R] [Algebra k R]
    [Algebra.FiniteType k R] {u : R}
    (h : ∀ χ : R →ₐ[k] AlgebraicClosure k, χ u ≠ 0) : IsUnit u

lemma ringAway_le {B : Subalgebra k (funField W)}
    (h₁ : ∀ c, algebraMap W.toAffine.CoordinateRing (funField W) c ∈ B)
    (h₂ : ∀ h, zeroSet W h ⊆ 𝒮 → (algebraMap _ (funField W) h)⁻¹ ∈ B) : ringAway W 𝒮 ≤ B

lemma exists_map_eq_of_toLaurent_mem {p : Polynomial K}
    (hp : Polynomial.toLaurent p ∈ integralLaurent O) :
    ∃ h : Polynomial O, h.map (algebraMap O K) = p

theorem mem_integralLaurent_of_eval_eq_zero [IsDomain O] [IsIntegrallyClosed O] {f : K[T;T⁻¹]}
    {q : Polynomial K[T;T⁻¹]} (hqm : q.Monic) (hq : ∀ i, q.coeff i ∈ integralLaurent O)
    (hf : q.eval f = 0) : f ∈ integralLaurent O

lemma sub_mem_lifts_valuationSubring {O : ValuationSubring k} {P Q : k[X]}
    (hP : P ∈ lifts (algebraMap O k)) (hQ : Q ∈ lifts (algebraMap O k)) :
    P - Q ∈ lifts (algebraMap O k)

theorem IsCoveringMap.countable_inter_fibre_of_isPreconnected {E Z : Type*} [TopologicalSpace E]
    [TopologicalSpace Z] [NoetherianSpace Z] {p : E → Z} (hp : IsCoveringMap p) {C : Set E}
    (hC : IsPreconnected C) (z : Z) : (C ∩ p ⁻¹' {z}).Countable

@[simp] lemma Hom.cast_toFun {P : CoveringCode ρ} {P' : CoveringCode ρ'} {ψ₁ ψ₂ : Z → Z'}
    {r₁ r₂ : G →* G'} (h : Hom P P' ψ₁ r₁) (hψ : ψ₁ = ψ₂) (hr : r₁ = r₂) :
    (h.cast hψ hr).toFun = h.toFun
